<script lang="ts">
  import { onMount } from "svelte";
  import { maybeEmitAnalyticsEvent, type DocsAnalyticsEvent } from "@docsfn/core/analytics";
  import type { DocsSearchArtifact, DocsSearchScope } from "@docsfn/core/search";
  import {
    createDocsSearchRuntime,
    type DocsSearchRuntime,
    type DocsSearchRuntimeResultItem,
  } from "@docsfn/core/search-runtime";
  import { Dialog, DialogPortal, DialogOverlay, DialogContent } from "@uifn/svelte";

  type SearchScopeFilter = DocsSearchScope | "all";

  export let searchArtifact: DocsSearchArtifact | undefined = undefined;
  export let searchIndex: DocsSearchArtifact | undefined = undefined;
  export let loadSearchArtifact: (() => Promise<DocsSearchArtifact>) | undefined =
    undefined;
  export let placeholder = "Search docs...";
  export let initialScope: SearchScopeFilter = "all";
  export let scopes: SearchScopeFilter[] = ["all", "docs", "api", "blog"];
  export let analytics:
    | {
        enabled?: boolean;
        respectDnt?: boolean;
        route?: string;
        onEvent?: (event: DocsAnalyticsEvent) => void;
      }
    | undefined = undefined;

  let isOpen = false;
  let query = "";
  let results: DocsSearchRuntimeResultItem[] = [];
  let selectedIndex = 0;
  let scope: SearchScopeFilter = initialScope;
  let inputRef: HTMLInputElement;
  let runtime: DocsSearchRuntime | null = null;
  let requestVersion = 0;

  function normalizeScopes(input: SearchScopeFilter[]): SearchScopeFilter[] {
    return [...new Set(input)].sort((left, right) =>
      left.localeCompare(right, "en", { sensitivity: "variant", numeric: true })
    );
  }

  $: supportedScopes = normalizeScopes(scopes);
  $: runtime = createDocsSearchRuntime({
    artifact: searchArtifact ?? searchIndex,
    loadArtifact: loadSearchArtifact,
  });

  async function runQuery() {
    if (!runtime || query.trim().length === 0) {
      results = [];
      selectedIndex = 0;
      return;
    }

    const currentVersion = ++requestVersion;
    try {
      const nextResults = await runtime.query({
        query,
        scope,
        limit: 10,
      });
      if (requestVersion !== currentVersion) {
        return;
      }
      results = nextResults;
      selectedIndex = 0;
      maybeEmitAnalyticsEvent({
        enabled: Boolean(analytics?.enabled),
        respectDnt: analytics?.respectDnt ?? true,
        event: {
          name: "docs.search",
          timestamp: new Date().toISOString(),
          route: analytics?.route ?? window.location.pathname,
          searchScope: scope === "all" ? undefined : scope,
          resultCount: nextResults.length,
        },
        emit: (event) => analytics?.onEvent?.(event),
      });
    } catch {
      if (requestVersion !== currentVersion) {
        return;
      }
      results = [];
      selectedIndex = 0;
    }
  }

  $: void runQuery();

  onMount(() => {
    const handleKeydown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        isOpen = true;
      }
    };
    window.addEventListener("keydown", handleKeydown);
    return () => window.removeEventListener("keydown", handleKeydown);
  });

  $: if (isOpen && inputRef) {
    inputRef.focus();
  }

  function handleKeyDown(event: KeyboardEvent) {
    if (results.length === 0) {
      return;
    }
    if (event.key === "ArrowDown") {
      event.preventDefault();
      selectedIndex = Math.min(selectedIndex + 1, results.length - 1);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      selectedIndex = Math.max(selectedIndex - 1, 0);
    } else if (event.key === "Enter" && results[selectedIndex]) {
      event.preventDefault();
      handleResultClick(results[selectedIndex]);
    }
  }

  function handleResultClick(result: DocsSearchRuntimeResultItem) {
    maybeEmitAnalyticsEvent({
      enabled: Boolean(analytics?.enabled),
      respectDnt: analytics?.respectDnt ?? true,
      event: {
        name: "docs.search_result_click",
        timestamp: new Date().toISOString(),
        route: analytics?.route ?? window.location.pathname,
        searchScope: result.scope,
        targetUrl: result.path,
      },
      emit: (event) => analytics?.onEvent?.(event),
    });
    window.location.href = result.path;
    isOpen = false;
  }

  function handleOpenChange(open: boolean) {
    isOpen = open;
    if (!open) {
      query = "";
      results = [];
      selectedIndex = 0;
    }
  }
</script>

<Dialog bind:open={isOpen} onOpenChange={handleOpenChange}>
  <button
    class="docsfn-search-trigger"
    on:click={() => (isOpen = true)}
    aria-label="Search documentation"
  >
    <span class="docsfn-search-icon" aria-hidden="true">🔍</span>
    <span class="docsfn-search-placeholder">{placeholder}</span>
    <kbd class="docsfn-search-kbd">
      <span>⌘</span>
<script lang="ts">
  import type { DocsTopNavItem } from "@docsfn/core/browser";
  import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
  } from "@uifn/svelte";
  import type { DocsPageSurface } from "./DocsLayout.svelte";

  export interface TopBarLink {
    label: string;
    href: string;
    external?: boolean;
  }

  export interface TopBarDropdown {
    label: string;
    items: TopBarLink[];
  }

  export type TopBarItem = TopBarLink | TopBarDropdown;

  export let surface: DocsPageSurface | undefined = undefined;
  export let logo: any = undefined;
  export let items: TopBarItem[] | undefined = undefined;
  export let searchTrigger: any = undefined;
  export let versionSelector: any = undefined;
  export let mobileMenuTrigger: any = undefined;

  function mapTopNavItems(topNav: DocsTopNavItem[]): TopBarItem[] {
    return topNav.map((item) => {
      if (Array.isArray(item.children) && item.children.length > 0) {
        return {
          label: item.label,
          items: item.children.map((child) => ({
            label: child.label,
            href: child.href,
            external: child.external,
          })),
        };
      }

      return {
        label: item.label,
        href: item.href,
        external: item.external,
      };
    });
  }

  function isDropdown(item: TopBarItem): item is TopBarDropdown {
    return "items" in item;
  }

  $: resolvedItems = items ?? mapTopNavItems(surface?.topNav ?? []);
</script>

<header class="docsfn-topbar">
  <div class="docsfn-topbar-container">
    <!-- Logo -->
    {#if logo}
      <div class="docsfn-topbar-logo">
        <svelte:component this={logo} />
      </div>
    {/if}

    <!-- Desktop Navigation -->
    <nav class="docsfn-topbar-nav" aria-label="Main navigation">
      {#each resolvedItems as item, index (`${item.label}:${index}`)}
        {#if isDropdown(item)}
          <DropdownMenu>
            <DropdownMenuTrigger class="docsfn-topbar-dropdown-trigger">
              {item.label}
              <svg
                width="12"
                height="12"
                viewBox="0 0 12 12"
                fill="none"
                aria-hidden="true"
