import pathlib,subprocess as s,concurrent.futures
root=pathlib.Path.cwd(); shared=root/'apifn/docs/node_modules'
funcs=['apifn','botfn','clifn','devfn','extfn','langfn','mailfn','mcpfn','mdfn','memoryfn','plugfn','reviewfn','secfn','sendfn']
for f in funcs:
 p=root/f/'docs/node_modules'
 if not p.exists():p.symlink_to(shared,target_is_directory=True)
def run(f):
 cwd=root/f/'docs'
 out=s.run([str(shared/'.bin/docsfn'),'validate','--root','.'],cwd=cwd,capture_output=True,text=True)
 (root/(f+'-validate.log')).write_text(out.stdout+out.stderr)
 b=s.run(['npm','run','build'],cwd=cwd,capture_output=True,text=True)
