export type MdfnRemoteVersionSummary = Omit<MdfnRemoteVersion, "markdown" | "sidecar">;
export interface MdfnRemoteVersionBatch { readonly versions: readonly MdfnRemoteVersionSummary[]; readonly nextCursor?: string; }

