                admin: z.boolean(),
                maintain: z.boolean().optional(),
                push: z.boolean(),
                triage: z.boolean().optional(),
                pull: z.boolean(),
              })
              .optional(),
          })
          .passthrough(),
      ),

      execute: async (params: any, context: ActionContext) => {
        const queryParams: Record<string, unknown> = {
