      tenantId: input.tenantId,
      mode: input.mode,
      checkpoint: input.checkpoint,
      cursor: input.cursor,
    },
    cache: false,
  });

  if (!result.success) {
    throw result.error;
  }

  const data = (result.data ?? {}) as Record<string, unknown>;
