    this.queryTimeoutMs = options.queryTimeoutMs ?? 30_000;
    this.maxBatchSize = options.maxBatchSize ?? 10_000;
    this.defaults = options.defaults ?? {};
    this.logger = postgresLoggerFromObservability(observability?.logger);
