function parseFrontmatter(source: string): {
  body: string;
  frontmatter: Record<string, unknown>;
} {
  if (!source.startsWith("---\n")) {
    return { body: source, frontmatter: {} };
  }

  const closingIndex = source.indexOf("\n---", 4);
  if (closingIndex === -1) {
