Description: Notable changes to DataFn across releases.
--------------------------------------------------------------------------------

This is the human-readable changelog. For machine-readable release metadata see the [GitHub releases page](https://github.com/21nCo/super-functions/releases).

DataFn follows [semver](https://semver.org/): until 1.0 minor versions may include breaking changes that are called out below.

## Unreleased

- Canonical structural resource-selector extraction: `parseDatafnRequest`, `collectStructuralResourceSelectors`, and `extractStructuralResourceSelectors` in `@datafn/core` (re-exported from `@datafn/server`). Gateways and `authorize` plugins should use this API instead of traversing request JSON. Unsupported `protocolVersion` values return `DATAFN_UNSUPPORTED_PROTOCOL_VERSION`.
**New**

- Versioned namespace storage contract: `DATAFN_NAMESPACE_STORAGE_MANIFEST` in `@datafn/core` and `resolveNamespaceStoragePlan` / `inspectPostgresNamespaceStorage` / `drainNamespaceStorage` in `@datafn/server`. This is the supported integration point for tenant copy, checksum, cleanup, write fencing, outbox drain, backup, and physical-ownership checks.

## 0.3.0

**New**

- `shareable` capability with record-scope and resource-scope variants.
- WebSocket-based live cursor notifications under `/datafn/ws`.
- `SearchProvider` interface for cross-resource search.
- Apple runtime: `DatafnObservedQuery` for `@Observable` SwiftUI integration.
- Apple runtime: WebView bridge host (`DatafnWKWebViewBridgeHost`) for hybrid apps.
/**
 * Plugin hook runner for server-side plugins
 * Delegates to shared @datafn/core hook runner with env: "server"
 */

import type { DatafnPlugin, DatafnHookContext, HookError } from "../core-types.js";
import { runBeforeHook, runAfterHook } from "@datafn/core";
import type { DatafnLogger } from "../logger.js";

export type { HookError };

export async function runBeforeQuery(
  query: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any; context?: unknown },
  plugins: DatafnPlugin[],
): Promise<{ ok: true; query: unknown } | { ok: false; error: HookError }> {
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema, context: ctx.context };
  const result = await runBeforeHook(plugins, "server", "beforeQuery", hookCtx, query);
  if (!result.ok) return { ok: false, error: result.error };
  return { ok: true, query: result.value };
}

export async function runBeforeSearch(
  search: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any; context?: unknown },
  plugins: DatafnPlugin[],
): Promise<{ ok: true; search: unknown } | { ok: false; error: HookError }> {
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema, context: ctx.context };
  const result = await runBeforeHook(plugins, "server", "beforeSearch", hookCtx, search);
  if (!result.ok) return { ok: false, error: result.error };
  return { ok: true, search: result.value };
}

export async function runAfterQuery(
  query: unknown,
  result: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any },
  plugins: DatafnPlugin[],
  logger?: DatafnLogger,
): Promise<unknown> {
  // LOW-006: Capture return value from afterQuery hooks so plugins can transform/redact results.
  // runAfterHook ignores return values; we implement the loop inline to capture them.
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema };
  let current = result;
  const filtered = plugins.filter((p) => p.runsOn.includes("server"));
  for (const plugin of filtered) {
    const hook = plugin.afterQuery as ((ctx: DatafnHookContext, query: unknown, result: unknown) => Promise<unknown> | unknown) | undefined;
    if (!hook) continue;
    try {
      const returned = await hook(hookCtx, query, current);
      if (returned !== undefined) current = returned;
    } catch (err) {
      logger?.error("Plugin afterQuery error", { plugin: plugin.name, error: String(err), operation: "plugin" });
    }
  }
  return current;
}

export async function runBeforeMutation(
  mutation: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any },
  plugins: DatafnPlugin[],
): Promise<{ ok: true; mutation: unknown } | { ok: false; error: HookError }> {
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema };
  const result = await runBeforeHook(plugins, "server", "beforeMutation", hookCtx, mutation);
  if (!result.ok) return { ok: false, error: result.error };
  return { ok: true, mutation: result.value };
}

