          file: namedFile,
          fileName: extractFileName(converted, outputFileName),
          mimeType: convertedMimeType,
          localSource: {
            kind: 'image',
            previewBehavior: 'direct-image',
          },
        };
      } catch (error) {
        throw buildClientError(
          FILEFN_HEIC_CONVERSION_FAILED,
          'HEIC conversion failed',
          error,
        );
      }
    },
  };
}
