import type { DocsConfig } from "@docsfn/core";

const config: DocsConfig = {
  schemaVersion: 1,
  site: {
    title: "McpFn",
    description: "Build, secure, test, and evolve Model Context Protocol servers with stable consumer contracts.",
    basePath: "/docs",
    editLink: { pattern: "https://github.com/21nCo/super-functions/edit/dev/mcpfn/docs/{path}" },
  },
  compat: { preset: "none" },
  content: {
    root: ".",
    docsDir: "content/docs",
    pagesDir: "content/pages",
    blogDir: "content/blog",
    apiDir: "content/api",
    assetsDir: "static",
    metaFileName: "meta.json",
  },
  navigation: {
    topNav: [
      { label: "Docs", href: "/docs" },
      { label: "Packages", href: "/docs/reference" },
      { label: "GitHub", href: "https://github.com/21nCo/super-functions/tree/dev/mcpfn", external: true },
    ],
    sidebars: {
      docs: { title: "Documentation", root: true, include: ["docs/**"] },
    },
  },
  search: { enabled: true, scopes: ["docs"], bodyIndexing: "summary" },
  auth: { enabled: false, mode: "public" },
  analytics: { enabled: false, provider: "watchfn", respectDnt: true },
};

export default config;
<script lang="ts">
  import DocsContent from "@docsfn/svelte/DocsContent.svelte";
  import DocsLayout from "@docsfn/svelte/DocsLayout.svelte";
  import ApiReferenceRenderer from "@docsfn/svelte/ApiReferenceRenderer.svelte";
  import Breadcrumbs from "@docsfn/svelte/Breadcrumbs.svelte";
  import Pagination from "@docsfn/svelte/Pagination.svelte";
  import type { PageData } from "./$types";

  interface Props {
    data: PageData;
  }

  let { data }: Props = $props();
</script>

<svelte:head>
  <title>{data.surface.title ?? data.siteTitle}</title>
  {#if data.surface.description}
    <meta name="description" content={data.surface.description} />
  {/if}
</svelte:head>

<DocsLayout surface={data.surface} sidebar={data.sidebar}>
  <Breadcrumbs surface={data.surface} />
  {#if data.routeEntry.kind === "page" && data.compiled}
    <article class="docs-page-article">
      <DocsContent compiled={data.compiled} />
    </article>
  {:else if data.routeEntry.kind === "api"}
    <article class="docs-page-article">
      <ApiReferenceRenderer api={data.routeEntry.api} />
    </article>
  {/if}
  <Pagination surface={data.surface} />
</DocsLayout>

<style>
  .docs-page-article {
    margin-top: 0.5rem;
  }
</style>
